const Theme=createContext<'light'|'dark'>('light');
function ThemeBadge(){return <span>Theme: {useContext(Theme)}</span>;}
function Settings(){return <Theme.Provider value="dark"><ThemeBadge /></Theme.Provider>;}

function Search(){
  const [query,setQuery]=useState('');
  const [results,setResults]=useState<string[]>([]);
  const [pending,startTransition]=useTransition();
  return <><input value={query} onChange={e=>{
    setQuery(e.target.value);
    startTransition(()=>setResults(filterItems(e.target.value)));
  }}/><output aria-busy={pending}>{results.length} matches</output></>;
}

