  const title=String(form.get('title')??'').trim();
  return {error:title?'':'Required'};
},{error:''});

productionExample:
function SubmitDraft(){
  const [state,action,pending]=useActionState(saveAuthorizedDraft,{error:''});
  return <form action={action}><label>Title<input name="title" required /></label>
    <button disabled={pending}>Save</button><p role="status">{state.error}</p></form>;
}
// saveAuthorizedDraft must validate and authorize on the server.
